// Compares X-HelloHop-Signature with the HMAC computed by "Compute HMAC-SHA256 of raw body".
// Plain JavaScript on purpose, so the workflow runs without enabling any Node modules:
// it checks the length first, then XORs EVERY character with no early exit. That removes
// the early-exit timing leak of ===; it is not a guaranteed constant-time compare.
// If your n8n lets the Code node use the crypto module, crypto.timingSafeEqual is the
// stronger choice (keep the length check, because it throws on unequal lengths).
const expected = String($json.expected_signature || '');
const headers = $('Receive HelloHop webhook').first().json.headers || {};
const given = String(headers['x-hellohop-signature'] || '');

let valid = expected.length === 64 && given.length === expected.length;
if (valid) {
  let diff = 0;
  for (let i = 0; i < expected.length; i++) {
    diff |= expected.charCodeAt(i) ^ given.charCodeAt(i);
  }
  valid = diff === 0;
}

// The body was signed as raw bytes; the Webhook node also parsed it into json.body.
const event = valid ? $('Receive HelloHop webhook').first().json.body : null;

// Skip repeats: HelloHop delivers at least once and a retry keeps the same body id.
// Static data persists only for published (production) executions.
let duplicate = false;
if (valid && event && event.id) {
  const store = $getWorkflowStaticData('global');
  store.seen = store.seen || [];
  duplicate = store.seen.includes(event.id);
  if (!duplicate) {
    store.seen.push(event.id);
    if (store.seen.length > 500) store.seen = store.seen.slice(-500);
  }
}

return [{ json: { valid, duplicate, event } }];
